import { useState } from 'react'

import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import { TodoAlreadyCompletedError } from '../../application/TodoCompleter'
import type { TodoViewModel } from '../../application/TodoViewModel'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

type TodoItemProps = {
  todo: TodoViewModel
}

export const TodoItem = ({ todo }: TodoItemProps) => {
  const { completeTodo } = useTodosUseCases()
  const [done, setDone] = useState(todo.status === 'done')
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const complete = async () => {
    if (!completeTodo) return
    setPending(true)
    setError(null)
    try {
      await completeTodo.execute(todo.id)
      setDone(true)
    } catch (cause) {
      if (cause instanceof TodoAlreadyCompletedError) {
        setDone(true)
        setError('This todo is already completed.')
      } else {
        setError('The todo could not be completed.')
      }
    } finally {
      setPending(false)
    }
  }

  return (
    <li>
      {todo.title}
      {done ? ' (done)' : null}
      {!done && completeTodo ? (
        <button type="button" disabled={pending} onClick={() => void complete()}>
          Complete
        </button>
      ) : null}
      {error ? <ErrorMessage>{error}</ErrorMessage> : null}
    </li>
  )
}
